changeSet.sql:
declare
v_jobs number;
begin
select count(*)
into v_jobs
from user_jobs
where upper(what) like ('%UTENTE.SISTEMA_POSIZIONE_GRUPPI(''%'')%');
if v_jobs = 0 then
DECLARE
X NUMBER;
BEGIN
SYS.DBMS_JOB.SUBMIT
( job       => X
,what      => 'begin UTENTE.SISTEMA_POSIZIONE_GRUPPI(''%''); end;'
,next_date => sysdate
,interval  => 'trunc(sysdate +1) + 2/24'
,no_parse  => FALSE
);
COMMIT;
END;
end if;
end;
/
